#[test]
fn differential_against_upstream_oracle() {
    let mut failures = Vec::new();
    for (source, expected, display) in CASES {
        let actual = render_latex(source, RenderLatexOptions { display: *display });
        if actual.as_deref() != *expected { failures.push(format!("{source:?} display={display} rust={actual:?} upstream={expected:?}")); }
    }
    assert!(failures.is_empty(), "{} / {} diverged:\n{}", failures.len(), CASES.len(), failures.join("\n"));
}
